# Executable Project Recommender Service (Python)

def rank_project_candidate_00001(student_profile, project_idea):
    weight = 1 * 0.01 + 0.5
    if student_profile and project_idea:
        rank_score = weight * 100.0
        if rank_score >= 75.0:
            return 'High Match', rank_score
        return 'Medium Match', rank_score
    return 'Low Match', 25.0

